//! Unique original Sys Loot roots and rules over borrowed original source.
use std::collections::{BTreeSet,HashSet};
use crate::{tree::SourceFile,dm::sys::col0,pat,util::before_slashes,key_policy_control::{self as kc,Control}};
pub use crate::allow_registry_fields::sys_loot::RULES;
fn row<C:Control,T>(c:&mut C,rows:&mut Vec<T>)->Result<(),C::Error>{if !C::CHECKED||rows.len()<rows.capacity(){return Ok(())}let target=rows.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;kc::reserve(c,||bound.checked_mul(std::mem::size_of::<T>())?.checked_add(128))?;rows.try_reserve_exact(target-rows.len()).map_err(|_|c.allocation_failed())?;if rows.capacity()>bound{return Err(c.allocation_failed())}Ok(())}
fn owner<C:Control>(text:&str,c:&mut C,peak:&mut usize)->Result<String,C::Error>{if C::CHECKED{let bytes=text.len().checked_mul(4).and_then(|n|n.checked_add(128)).ok_or_else(||c.overflow())?;if bytes>*peak{c.reserve(bytes-*peak)?;*peak=bytes;}}Ok(text.to_owned())}
pub fn roots_of_using<C:Control>(f:&SourceFile,c:&mut C)->Result<Vec<String>,C::Error>{let mut roots=BTreeSet::new();let mut cur=None;let mut peak=0;for line in f.raw().lines(){c.checkpoint()?;if let Some(capture)=kc::captures_static(c,r"^CAPABILITIES(?:_PART)?\((/[\w/]+)[,)]",line,0,||pat!(r"^CAPABILITIES(?:_PART)?\((/[\w/]+)[,)]"))?{cur=Some(owner(capture.s(1),c,&mut peak)?);continue}if col0(line){cur=None;continue}if let Some(t)=&cur{if kc::is_match_static(c,r"^\t(configure\()?map_resolver\(",line,||pat!(r"^\t(configure\()?map_resolver\("))?&&!roots.contains(t){kc::reserve(c,||Some(2048))?;roots.insert(kc::own(c,t)?);}}}let mut output=Vec::new();for root in roots{c.checkpoint()?;row(c,&mut output)?;output.push(root);}Ok(output)}
pub fn roots_of(f:&SourceFile)->Vec<String>{roots_of_using(f,&mut kc::Compatibility).unwrap_or_else(|never|match never{})}
pub fn judge_using<C:Control>(f:&SourceFile,roots:&HashSet<String>,out:&mut Vec<(&'static str,usize)>,c:&mut C)->Result<(),C::Error>{let mut cur=None;let mut peak=0;for(number,line)in f.raw().numbered(){c.checkpoint()?;let code=before_slashes(line);if kc::is_match_static(c,r"\bitem_to_spawn\b",code,||pat!(r"\bitem_to_spawn\b"))?{row(c,out)?;out.push(("item_to_spawn",number));}if kc::is_match_static(c,r"/datum/loot_table\b|\bloot_table_type\b|\bloot_reward\s*\(",code,||pat!(r"/datum/loot_table\b|\bloot_table_type\b|\bloot_reward\s*\("))?{row(c,out)?;out.push(("loot_table_datum",number));}if kc::is_match_static(c,r"^/obj/random(_multi)?(/[\w/]*)?/(proc/|verb/)?\w+\(",code,||pat!(r"^/obj/random(_multi)?(/[\w/]*)?/(proc/|verb/)?\w+\("))?{row(c,out)?;out.push(("random_spawn_list",number));}if let Some(capture)=kc::captures_static(c,r"^(/[\w/]+)\s*(//.*)?$",line,0,||pat!(r"^(/[\w/]+)\s*(//.*)?$"))?{cur=Some(owner(capture.s(1),c,&mut peak)?);continue}if col0(line){cur=None;continue}if let Some(owner)=&cur{if kc::is_match_static(c,r"^\t(var/(list/)?)?(spawn_types|to_spawn|possible_\w+|items|\w+_loot)\s*=\s*list\(",code,||pat!(r"^\t(var/(list/)?)?(spawn_types|to_spawn|possible_\w+|items|\w+_loot)\s*=\s*list\("))?&&crate::dm::sys::in_family_using(owner,roots,c)?{row(c,out)?;out.push(("random_spawn_list",number));}}}c.checkpoint()}
pub fn judge(f:&SourceFile,roots:&HashSet<String>,out:&mut Vec<(&'static str,usize)>){judge_using(f,roots,out,&mut kc::Compatibility).unwrap_or_else(|never|match never{})}
